commands.command:
/usr/bin/zsh -lc "cat > index.html <<'EOF'
<"'!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>FIELD NOTES</title>
  <style>
    :root {
      color-scheme: light;
      background: #f6f3eb;
      color: #163b43;
      font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    }

    * { box-sizing: border-box; }
    body { margin: 0; }
    .page { width: min(100% - 96px, 1440px); margin-inline: auto; }

    header {
      padding-block: 30px;
      border-bottom: 1px solid #163b43;
      font-size: 14px;
      font-weight: 700;
      letter-spacing: 0.14em;
    }

    .intro {
      min-height: 680px;
      min-height: min(80svh, 900px);
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      gap: 64px;
      padding-block: 78px 64px;
    }

    h1 {
      max-width: 11ch;
      margin: 0;
      font-size: clamp(64px, 10.5vw, 152px);
      font-weight: 400;
      line-height: 0.98;
      letter-spacing: -0.065em;
    }

    .intro-bottom {
      display: flex;
      align-items: flex-end;
      justify-content: space-between;
      gap: 32px;
    }

    p {
      margin: 0;
      max-width: 23ch;
      font-size: clamp(20px, 2.1vw, 30px);
      line-height: 1.35;
      letter-spacing: -0.025em;
    }

    .explore {
      flex: 0 0 112px;
      width: 112px;
      height: 112px;
      display: grid;
      place-items: center;
      border: 1px solid #163b43;
      border-radius: 0;
      background: #163b43;
      color: #f6f3eb;
      font-size: 16px;
      font-weight: 500;
      text-decoration: none;
    }

    .explore:hover { text-decoration: underline; text-underline-offset: 5px; }
    .explore:focus-visible { outline: 3px solid #163b43; outline-offset: 5px; }

    #work {
      padding-block: 28px 64px;
      border-top: 1px solid #163b43;
      scroll-margin-top: 24px;
    }

    h2 {
      margin: 0 0 32px;
      font-size: clamp(24px, 3vw, 40px);
      line-height: 1.15;
      font-weight: 400;
      letter-spacing: -0.035em;
    }

    .work-image { display: block; width: 100%; height: auto; }

    @media (max-width: 600px) {
      .page { width: calc(100% - 40px); }
      header { padding-block: 24px; font-size: 12px; }
      .intro { min-height: 620px; min-height: 78svh; padding-block: 56px 40px; }
      h1 { font-size: clamp(56px, 16vw, 96px); }
      .intro-bottom { align-items: flex-start; gap: 24px; }
      p { max-width: 15ch; }
      .explore { flex-basis: 88px; width: 88px; height: 88px; font-size: 14px; }
      #work { padding-block: 24px 40px; }
      h2 { margin-bottom: 24px; }
    }
  </style>
</head>
<body>
  <div class="page">
    <header>FIELD NOTES</header>
    <main>
      <section class="intro" aria-labelledby="intro-heading">
        <h1 id="intro-heading">A quiet study.</h1>
        <div class="intro-bottom">
          <p>An independent film practice.</p>
          <a class="explore" href="#work">Explore</a>
        </div>
      </section>
      <section id="work" aria-labelledby="work-heading">
        <h2 id="work-heading">Selected work</h2>
        <img class="work-image" src="assets/poster.svg" width="960" height="540" alt="">
      </section>
    </main>
  </div>
</body>
</html>
EOF
cat > NOTES.md <<'"'EOF'
Static FIELD NOTES page: index.html. Local qs-design-frontend guidance and relevant brief, direction, implementation, and restrained references read.
Parameters: effort=standard; report=brief; #f6f3eb background; #163b43 text; system sans; square Explore anchor to #work. Exact supplied copy; two sections. Local poster.svg used as a decorative still; fixture rights recorded in assets/rights.json.
No scripts, motion, transitions, animation, video, external resources, or dependencies.
Validation: shell content checks only. Browser/runtime, rendered responsiveness, and keyboard behavior unverified; reserved for the central observer.
EOF
expected_text='FIELD NOTES|A quiet study\\.|An independent film practice\\.|Explore|Selected work'
rg -n \""'$expected_text|href=|src=|background:|color:|font-family:|border-radius:" index.html
if rg -ni '"'<script|<video|<iframe|animation\\s*:|transition\\s*:|https?://|@import|scroll-behavior' index.html; then
  exit 1
fi
[ \""'$(rg -c '"'<section' index.html)\" = 2 ] && [ \""'$(rg -c '"'href=' index.html)\" = 1 ] && [ -f assets/poster.svg ] && printf 'Static content checks passed.\\n'"
